export default function Home(){const[student,setStudent]=useState(''),[level,setLevel]=useState<L>('Standard'),[round,setRound]=useState(0),[answer,setAnswer]=useState(''),[msg,setMsg]=useState(''),[showHint,setShowHint]=useState(false),[tab,setTab]=useState<'Mission'|'Map Lab'|'Park Map'|'Park Atlas'|'Black History'>('Mission'),[attempts,setAttempts]=useState<A[]>([]),[settings,setSettings]=useState<Record<string,L>>({}),[login,setLogin]=useState(false),[teacher,setTeacher]=useState(false),[u,setU]=useState(''),[pw,setPw]=useState(''),[review,setReview]=useState(kids[0]);const mission=useMemo(()=>q(round,level),[round,level]),mine=attempts.filter(a=>a.student===student);useEffect(()=>{fetch(`/api/student?student=${encodeURIComponent(student)}`).then(r=>r.json()).then(x=>setLevel(x.difficulty||'Standard'))},[student]);useEffect(()=>{if(teacher)fetch('/api/classroom').then(r=>r.json()).then(x=>{setAttempts(x.attempts||[]);setSettings(x.settings||{})})},[teacher]);function save(prompt:string,answer:string,topic:string,chosen:string){const typed=chosen.trim(),cityState=placeState(typed),cityMatch=!!cityState&&clean(cityState)===clean(answer),correct=clean(typed)===clean(answer)||cityMatch,row:A={id:crypto.randomUUID(),student,prompt,topic,given:typed||'—',answer,correct,when:new Date().toISOString(),difficulty:level,xp:correct?xp(level):0};setAttempts(x=>[...x,row]);fetch('/api/classroom',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(row)});setMsg(correct?(cityMatch?`Technically correct — ${typed} is in ${answer}. I was asking for the state, so the full answer is ${answer}. +${row.xp} XP`:`Excellent! +${row.xp} XP${level==='Harder'?' for a harder mission!':''}`):`Not quite — ${answer} is the answer.`)}async function sign(e:React.FormEvent){e.preventDefault();const r=await fetch('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:u,password:pw})});if(r.ok){setTeacher(true);setLogin(false)}else setMsg('Teacher sign-in did not match.')}async function assign(v:L){setSettings(x=>({...x,[review]:v}));await fetch('/api/classroom',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({student:review,difficulty:v})})}
if(teacher){const rows=attempts.filter(a=>a.student===review).slice().reverse(),assigned=settings[review]||'Standard';return <main><nav><div className="brand"><b>★ STATE SCOUT</b><small>Teacher Atlas</small></div><button className="return" onClick={()=>setTeacher(false)}>← Student view</button></nav><section className="teacher"><header><p>TEACHER MODE · US EXPLORER</p><h1>Guide every explorer<br/><em>across the map.</em></h1><div className="classscore"><b>{pct(attempts)}%</b><span>class accuracy<br/>{attempts.length} saved answers</span></div></header><div className="dashboard"><aside><p>STUDENT PROFILES · 20</p>{kids.map((n,i)=>{const data=attempts.filter(a=>a.student===n);return <button key={n} className={review===n?'chosen':''} onClick={()=>setReview(n)}><i style={{background:colors[i%5]}}>{n[0]}</i><span><b>{n}</b><small>{pct(data)}% · {settings[n]||'Standard'}</small></span></button>})}</aside><section className="report"><div className="name"><div><p>EXPLORER REPORT</p><h2>{review}</h2></div><b>{pct(rows)}%<small>accuracy</small></b></div><article className="assign"><p>QUEST DIFFICULTY</p><h3>Choose {review}&apos;s next quest level</h3><span>Harder missions earn <b>20 XP</b> when correct.</span><div>{(['Easier','Standard','Harder']as L[]).map(v=><button key={v} onClick={()=>assign(v)} className={assigned===v?v.toLowerCase():''}>{v==='Easier'?'↓ Easier':v==='Standard'?'◆ Standard':'↑ Harder'}<small>{v==='Harder'?'+20 XP credit':v==='Easier'?'Confidence builder':'Grade-level explorer work'}</small></button>)}</div></article><article className="insight"><b>Next focus</b><h3>{rows.some(a=>!a.correct)?'Review map locations':'Ready for deeper exploration!'}</h3><span>Current assignment: <strong>{assigned}</strong> missions</span></article><section className="history"><h3>Saved explorer history</h3>{rows.length?rows.map(a=><div className="row" key={a.id}><i className={a.correct?'yes':'no'}>{a.correct?'✓':'!'}</i><span><b>{a.topic} <mark>{a.difficulty}</mark></b><small>{a.prompt}</small></span><em>{a.given}<small>Correct: {a.answer} · +{a.xp} XP</small></em></div>):<p>No saved answers yet.</p>}</section></section></div></section></main>}
const total=mine.filter(a=>a.correct).reduce((n,a)=>n+a.xp,0);return <main><nav><div className="brand"><b>★ STATE SCOUT</b><small>US Geography Explorer</small></div><div className="nav"><button onClick={()=>setLogin(true)}>Teacher Mode</button><span>⚡ {mine.filter(a=>a.correct).length} streak</span><strong>✦ {total} XP</strong></div></nav><div className="tabs">{(['Mission','Map Lab','Park Map','Park Atlas','Black History']as const).map(x=><button className={tab===x?'on':''} onClick={()=>setTab(x)} key={x}>{x}</button>)}</div><section className="shell"><aside className="roster"><p>EXPLORER CREW <b>20</b></p>{kids.map((n,i)=><button key={n} className={student===n?'active':''} onClick={()=>{setStudent(n);setRound(i);setAnswer('');setMsg('');setShowHint(false)}}><i style={{background:colors[i%5]}}>{n[0]}</i>{n}</button>)}</aside><section className="mission">{!student?<div className="student-select"><p>READY TO EXPLORE?</p><h1>Select which student<br/><em>is playing.</em></h1><span>Choose your name from the Explorer Crew to begin your geography adventure.</span></div>:<>{tab==='Mission'&&<><p>{level.toUpperCase()} EXPLORER MISSION</p><h1>Discover the United States,<br/><em>{student.split(' ')[0]}.</em></h1><label className={level.toLowerCase()}>{level==='Harder'?'↑ Harder mission · double XP':level==='Easier'?'↓ Easier mission':'◆ Standard mission'}</label><article><div><span>{mission.topic} · {level}</span><b>Mission 1 / 3</b></div><h2>{mission.prompt}</h2><input value={answer} onChange={e=>setAnswer(e.target.value)} onKeyDown={e=>e.key==='Enter'&&save(mission.prompt,mission.answer,mission.topic,answer)} placeholder="Type your answer"/><button onClick={()=>save(mission.prompt,mission.answer,mission.topic,answer)}>Check answer →</button><button className="hint-button" onClick={()=>setShowHint(x=>!x)}>{showHint?"Hide hint":"💡 Need a hint?"}</button>{showHint&&<div className="kid-hint"><b>Helpful hint</b><span>{mission.hint}</span></div>}{msg&&<p className="feedback">{msg} <a onClick={()=>{setRound(x=>x+1);setAnswer('');setMsg('');setShowHint(false)}}>Next mission</a></p>}<small>💡 {mission.fact}</small></article><button className="park-link" onClick={()=>setTab('Park Map')}>🗺️ See Our National Parks →</button></>}{tab==='Park Map'&&<ParkMap/>}{tab==='Map Lab'&&<MapLab onAnswer={(state)=>save(`Click the state for ${mission.topic}`,mission.answer,'Interactive Map',state)} target={mission.answer}/>} {tab==='Park Atlas'&&<Atlas/>}{tab==='Black History'&&<History/>}</>}</section><aside className="right"><div><p>YOUR ATLAS</p><h3>Current level</h3><b className="big">{level}</b><span>{level==='Harder'?'Correct answers earn 20 XP.':'Your teacher chose this mission level.'}</span></div><div><p>QUESTION VAULT</p><b className="percent">{questionVault.length.toLocaleString()}+</b><span>geography questions, clues, and map challenges to explore.</span></div><div className="tip">★ Map maker tip<br/><small>Click Map Lab to practice location skills.</small></div></aside></section>{login&&<div className="overlay"><form onSubmit={sign}><button type="button" onClick={()=>setLogin(false)}>×</button><p>TEACHER MODE</p><h2>Welcome, map guide.</h2><label>Username<input value={u} onChange={e=>setU(e.target.value)}/></label><label>Password<input type="password" value={pw} onChange={e=>setPw(e.target.value)}/></label><button>Enter Teacher Mode →</button></form></div>}</main>}
